import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    This function implements the Quickselect algorithm to find the k-th largest element
    in an unsorted list. The average time complexity is O(n), while the worst-case 
    time complexity is O(n^2).
    """
    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]  # Move pivot to end
        store_index = left
        for i in range(left, right):
            if nums[i] > pivot_value:  # We want the k-th largest, so use >
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        nums[right], nums[store_index] = nums[store_index], nums[right]  # Move pivot to its final place
        return store_index

    def quickselect(left, right, k):
        if left == right:
            return nums[left]
        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)
        if k == pivot_index:
            return nums[k]
        elif k < pivot_index:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    return quickselect(0, len(nums) - 1, k - 1)

def kth_largest(nums: list[int], k: int) -> int:
    """
    This function implements the Heap Sort algorithm to find the k-th largest 
    element in an unsorted list. The time complexity is O(n log n).
    """
    def heapify(arr, n, i):
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and arr[left] > arr[largest]:
            largest = left
        if right < n and arr[right] > arr[largest]:
            largest = right

        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            heapify(arr, n, largest)

    n = len(nums)

    for i in range(n // 2 - 1, -1, -1):
        heapify(nums, n, i)

    for i in range(n - 1, n - k, -1):
        nums[0], nums[i] = nums[i], nums[0]
        heapify(nums, i, 0)

    return nums[0]

def kth_largest(nums: list[int], k: int) -> int:
    """
    This function implements the Modified Counting Sort algorithm to find the 
    k-th largest element in an unsorted list. The time complexity is O(n + m) 
    where n is the number of elements in the input list and m is the range 
    of the input values.
    """
    if not nums or k <= 0 or k > len(nums):
        raise ValueError("Invalid input.")

    max_value = max(nums)
    count = [0] * (max_value + 1)

    for num in nums:
        count[num] += 1

    # Traverse the count array from the end to find the k-th largest
    for i in range(len(count) - 1, -1, -1):
        if count[i] > 0:
            k -= count[i]
            if k <= 0:
                return i

    return -1  # Should not reach here if input is valid

def kth_largest(nums: list[int], k: int) -> int:
    """
    This function implements the Introselect algorithm, which is a hybrid 
    of Quickselect and Heapselect to find the k-th largest element in an 
    unsorted list. The average time complexity is O(n), while the worst-case 
    time complexity is O(n log n).
    """
    import statistics

    def introselect(left, right, k):
        while True:
            if left == right:
                return nums[left]

            pivot = statistics.median(nums[left:right + 1])
            pivot_index = partition(left, right, pivot)

            if k == pivot_index:
                return nums[k]
            elif k < pivot_index:
                right = pivot_index - 1
            else:
                left = pivot_index + 1

    def partition(left, right, pivot):
        pivot_index = left
        for i in range(left, right + 1):
            if nums[i] > pivot:
                nums[i], nums[pivot_index] = nums[pivot_index], nums[i]
                pivot_index += 1
        return pivot_index - 1

    return introselect(0, len(nums) - 1, k - 1)
